const cfg = $('Configuration').first().json;
// Fautes de frappe fréquentes sur les domaines grand public : corrigées, jamais devinées ailleurs.
const FAUTES = { 'gmial.com': 'gmail.com', 'gmai.com': 'gmail.com', 'gamil.com': 'gmail.com', 'hotmial.com': 'hotmail.com', 'hotmail.fe': 'hotmail.fr', 'yahooo.fr': 'yahoo.fr', 'outlok.com': 'outlook.com', 'orange.fe': 'orange.fr', 'wanadoo.fe': 'wanadoo.fr' };
const GENERIQUES = ['contact', 'info', 'bonjour', 'hello', 'admin', 'commercial', 'sales', 'support', 'noreply', 'no-reply'];

const brut = v => (v === null || v === undefined) ? '' : String(v);
const propre = v => brut(v).replace(/ +/g, ' ').trim();
const majuscules = v => propre(v).toLowerCase().replace(/(^|[ '-])([a-zà-ÿ])/g, (m, a, b) => a + b.toUpperCase());
const cle = v => propre(v).toLowerCase().normalize('NFD').replace(/[^a-z0-9]/g, '');

function email(v) {
  let e = propre(v).toLowerCase().replace(/ /g, '').replace(/[,;.]+$/, '');
  if (!e) return { valeur: '', etat: 'absent' };
  const [local, domaine] = e.split('@');
  if (domaine && FAUTES[domaine]) return { valeur: local + '@' + FAUTES[domaine], etat: 'corrige' };
  return /^[^@ ]+@[^@ ]+[.][a-z]{2,}$/.test(e) ? { valeur: e, etat: 'ok' } : { valeur: e, etat: 'invalide' };
}

// Numéros français ramenés au format international +33 ; les numéros étrangers déjà en +XX sont gardés.
function telephone(v) {
  const b = propre(v);
  if (!b) return { valeur: '', etat: 'absent' };
  let n = b.replace(/[^0-9+]/g, '');
  if (n.startsWith('00')) n = '+' + n.slice(2);
  if (n.startsWith('+33')) { n = n.slice(3); if (!n.startsWith('0')) n = '0' + n; }
  if (/^[1-9][0-9]{8}$/.test(n)) n = '0' + n;
  if (/^0[1-9][0-9]{8}$/.test(n)) return { valeur: '+33' + n.slice(1), etat: 'ok' };
  if (/^[+][1-9][0-9]{7,14}$/.test(n)) return { valeur: n, etat: 'ok' };
  return { valeur: b, etat: 'invalide' };
}

const fiches = $input.all().map((item, i) => {
  const c = item.json;
  const id = brut(c.id || i + 1);
  const mail = email(c.email);
  const tel = telephone(c.phone);
  const apres = { firstname: majuscules(c.firstname), lastname: majuscules(c.lastname), email: mail.valeur, phone: tel.valeur, company: propre(c.company), jobtitle: propre(c.jobtitle) };
  const problemes = [];
  let score = 100;
  if (mail.etat === 'absent') { problemes.push('e-mail manquant'); score -= 35; }
  if (mail.etat === 'invalide') { problemes.push('e-mail invalide'); score -= 35; }
  if (mail.etat !== 'invalide' && GENERIQUES.includes(apres.email.split('@')[0])) { problemes.push('adresse générique'); score -= 5; }
  if (tel.etat === 'absent') { problemes.push('téléphone manquant'); score -= 5; }
  if (tel.etat === 'invalide') { problemes.push('téléphone invalide'); score -= 10; }
  if (!apres.firstname || !apres.lastname) { problemes.push('nom incomplet'); score -= 15; }
  if (!apres.company) { problemes.push('entreprise manquante'); score -= 15; }
  if (!apres.jobtitle) { problemes.push('poste manquant'); score -= 10; }
  const corrections = {};
  for (const champ of Object.keys(apres)) {
    if (champ === 'email' && mail.etat === 'invalide') continue;
    if (champ === 'phone' && tel.etat === 'invalide') continue;
    if (apres[champ] && apres[champ] !== brut(c[champ])) corrections[champ] = apres[champ];
  }
  const cles = [];
  if (apres.email && mail.etat !== 'invalide') cles.push('email:' + apres.email);
  if (tel.etat === 'ok') cles.push('tel:' + apres.phone);
  if (apres.lastname && apres.company) cles.push('nom:' + cle(apres.firstname + apres.lastname) + '|' + cle(apres.company));
  const nom = (apres.firstname + ' ' + apres.lastname).trim() || apres.email || 'contact ' + id;
  return { id, nom, mail: mail.etat, problemes, score, corrections, cles };
});

// Regroupement des doublons : deux fiches qui partagent un e-mail, un téléphone ou nom + entreprise.
const parent = fiches.map((f, i) => i);
const racine = i => parent[i] === i ? i : (parent[i] = racine(parent[i]));
const vu = {};
fiches.forEach((f, i) => f.cles.forEach(k => { if (k in vu) parent[racine(i)] = racine(vu[k]); else vu[k] = i; }));
const groupes = {};
fiches.forEach((f, i) => { const r = racine(i); (groupes[r] = groupes[r] || []).push(i); });
const MOTIFS = { email: 'même e-mail', tel: 'même téléphone', nom: 'même nom et entreprise' };
const doublons = Object.values(groupes).filter(g => g.length > 1).map(g => {
  const compte = {};
  g.forEach(i => fiches[i].cles.forEach(k => { compte[k] = (compte[k] || 0) + 1; }));
  const motifs = [...new Set(Object.keys(compte).filter(k => compte[k] > 1).map(k => MOTIFS[k.split(':')[0]]))];
  g.forEach(i => { fiches[i].problemes.push('doublon probable'); fiches[i].score -= 15; });
  return { contacts: g.map(i => fiches[i].nom + ' (' + fiches[i].id + ')'), motifs };
});
fiches.forEach(f => { f.score = Math.max(0, f.score); });

const total = fiches.length;
const INCOMPLET = ['nom incomplet', 'entreprise manquante', 'poste manquant'];
return [{ json: {
  source: cfg.mode_demo ? 'exemple' : 'hubspot',
  date: $now.toISO(),
  total,
  score: total ? Math.round(fiches.reduce((s, f) => s + f.score, 0) / total) : 0,
  emails_a_corriger: fiches.filter(f => f.mail === 'absent' || f.mail === 'invalide').length,
  emails_normalises: fiches.filter(f => f.corrections.email).length,
  telephones_normalises: fiches.filter(f => f.corrections.phone).length,
  fiches_incompletes: fiches.filter(f => f.problemes.some(p => INCOMPLET.includes(p))).length,
  doublons,
  corrections: fiches.filter(f => Object.keys(f.corrections).length).map(f => ({ id: f.id, nom: f.nom, champs: f.corrections })),
  a_revoir: fiches.filter(f => f.problemes.length).sort((a, b) => a.score - b.score).slice(0, 15).map(f => ({ id: f.id, nom: f.nom, score: f.score, problemes: f.problemes }))
} }];

// L'API HubSpot accepte 100 fiches par lot de mise à jour.
const corrections = $input.first().json.corrections;
const lots = [];
for (let i = 0; i < corrections.length; i += 100) {
  lots.push({ json: { inputs: corrections.slice(i, i + 100).map(c => ({ id: c.id, properties: c.champs })) } });
}
return lots;

const r = $('Analyser la qualité').first().json;
const cfg = $('Configuration').first().json;
const envoye = $('Envoyer les corrections à HubSpot').isExecuted;
const esc = v => String(v === undefined || v === null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const couleur = r.score >= 80 ? '#1a7f37' : r.score >= 60 ? '#9a6700' : '#c62828';
const ligne = (a, b) => '<tr><td style="padding:6px 16px 6px 0;color:#57606a">' + a + '</td><td style="padding:6px 0;font-weight:600;text-align:right">' + b + '</td></tr>';

let ecriture;
if (cfg.mode_demo) ecriture = "Données d'exemple : rien n'a été écrit dans le CRM.";
else if (envoye) ecriture = r.corrections.length + ' fiches corrigées dans HubSpot (casse, espaces, formats). Les doublons ne sont jamais fusionnés automatiquement.';
else ecriture = r.corrections.length + " corrections prêtes, non appliquées : passez appliquer_corrections à vrai dans Configuration pour les écrire.";

let html = '<div style="font-family:Arial,Helvetica,sans-serif;max-width:640px;color:#1f2328;line-height:1.5">'
  + '<h2 style="margin:0 0 4px;font-size:20px">Qualité des données CRM</h2>'
  + '<p style="margin:0 0 20px;color:#57606a">' + r.total + ' contacts analysés, source : ' + (r.source === 'exemple' ? 'exemple' : 'HubSpot') + '</p>'
  + '<p style="margin:0 0 20px"><span style="font-size:40px;font-weight:700;color:' + couleur + '">' + r.score + '</span><span style="color:#57606a"> / 100</span></p>'
  + '<table style="border-collapse:collapse;margin-bottom:20px">'
  + ligne('Doublons probables', r.doublons.length)
  + ligne('E-mails manquants ou invalides', r.emails_a_corriger)
  + ligne('E-mails remis en forme', r.emails_normalises)
  + ligne('Téléphones au format international', r.telephones_normalises)
  + ligne('Fiches incomplètes', r.fiches_incompletes)
  + '</table>'
  + '<p style="margin:0 0 20px;padding:10px 12px;background:#f6f8fa;border-radius:6px">' + esc(ecriture) + '</p>';

if (r.doublons.length) {
  html += '<h3 style="font-size:16px;margin:0 0 8px">Doublons à trancher</h3><ul style="margin:0 0 20px;padding-left:18px">'
    + r.doublons.map(d => '<li>' + esc(d.contacts.join(' / ')) + ' <span style="color:#57606a">(' + esc(d.motifs.join(', ')) + ')</span></li>').join('')
    + '</ul>';
}
if (r.a_revoir.length) {
  html += '<h3 style="font-size:16px;margin:0 0 8px">Fiches à revoir en priorité</h3><table style="border-collapse:collapse;width:100%">'
    + r.a_revoir.map(f => '<tr><td style="padding:4px 12px 4px 0;font-weight:600">' + f.score + '</td><td style="padding:4px 12px 4px 0">' + esc(f.nom) + '</td><td style="padding:4px 0;color:#57606a">' + esc(f.problemes.join(', ')) + '</td></tr>').join('')
    + '</table>';
}
html += '</div>';

return [{ json: {
  html,
  objet: 'Qualité CRM : ' + r.score + '/100, ' + r.doublons.length + ' doublons probables',
  date: r.date,
  source: r.source,
  contacts: r.total,
  score: r.score,
  doublons: r.doublons.length,
  emails_a_corriger: r.emails_a_corriger,
  telephones_normalises: r.telephones_normalises,
  fiches_incompletes: r.fiches_incompletes,
  corrections_appliquees: envoye ? r.corrections.length : 0
} }];
